#!/usr/bin/env python3
"""Create the offline screenshot gallery and a bookmarked desktop review PDF."""
from pathlib import Path
import json,html
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4,landscape
from reportlab.lib.utils import ImageReader
root=Path(__file__).resolve().parents[1]
data=json.loads((root/'captures.json').read_text())
order=['Home','Family','Game','Analytics','Setup']
rows=data['results']
position={r['key']:i for i,r in enumerate(r for r in rows if r['size']=='desktop')}
rows.sort(key=lambda r:(order.index(r['group']),0 if r['key'].endswith('-menu') else 1,position[r['key']],r['width']))
data['results']=rows
payload=json.dumps(data,ensure_ascii=True).replace('</','<\\/')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>All Studio pages — owner review</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f5f3fa;color:#28233a;font:16px/1.5 system-ui,sans-serif}header,main{max-width:1500px;margin:auto;padding:24px}h1{margin:0;font-size:30px}p{max-width:1000px}.notice{background:#fff6d9;border:1px solid #d9b75e;padding:14px;border-radius:12px}.controls{display:flex;gap:10px;flex-wrap:wrap;position:sticky;top:0;background:#f5f3faf5;padding:12px 0;z-index:2}button,select,input,a.button{min-height:44px;padding:8px 14px;font:inherit;border:1px solid #a19ab9;border-radius:8px;background:white;color:inherit}button{cursor:pointer}button[aria-pressed=true]{background:#7040cc;color:white}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:20px}.card{padding:15px;background:white;border-radius:14px;border:1px solid #ded8ea}.card h3{font-size:18px;margin:5px 0}.card img{width:100%;height:290px;object-fit:contain;background:#eeeaf5}.card .links{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px}.small{font-size:13px;color:#625a76}.flag{color:#8a4200}.group{margin-top:28px}a{color:#6633b5}dialog{width:min(1500px,98vw);height:96vh;padding:0;border:0;border-radius:12px}dialog::backdrop{background:#171020cc}.viewerbar{display:flex;gap:8px;align-items:center;padding:10px;flex-wrap:wrap;border-bottom:1px solid #ddd}.viewerbar strong{flex:1}.picture{height:calc(96vh - 100px);overflow:auto;background:#e5e0ed;padding:10px;text-align:center}.picture img{max-width:100%;height:auto;box-shadow:0 2px 10px #0003}@media(max-width:600px){header,main{padding:14px}.controls{position:static}.picture{padding:0}.viewerbar strong{flex-basis:100%}}
</style><header><h1>Every Studio page, ready for review</h1><p>41 Studio pages, three section menus and sign-in. Choose desktop, tablet or phone; open a screenshot and use Previous/Next to review the whole Studio.</p><p class="notice"><strong>Synthetic preview.</strong> These are actual browser screenshots of the current Studio interface and routes, with invented records and in-memory providers. They are not production account or database screenshots. Unavailable/empty states remain visible. No real family data, invoices, payments or deployment actions were used.</p><p><a class="button" href="Studio-all-pages-desktop.pdf">Open the 45-page desktop PDF</a> · Full-page images and first-screen images are included. Very long pages have a collapsed overview, clearly labelled.</p></header>
<main><div class="controls"><button data-size="desktop" aria-pressed="true">Desktop · 1440</button><button data-size="tablet" aria-pressed="false">Tablet · 820</button><button data-size="phone" aria-pressed="false">Phone · 390</button><select id="section" aria-label="Section"><option>All sections</option><option>Home</option><option>Family</option><option>Game</option><option>Analytics</option><option>Setup</option></select><input id="search" type="search" placeholder="Find a page" aria-label="Find a page"></div><p id="count"></p><div id="pages"></div><p class="small">Application source: <a href="https://github.com/nguyentuanphu/tpn/tree/35bffe6ad5d8ca757ed60a49be670bca08b38f86">35bffe6a</a>. English captures. The separate implementation handbook includes Vietnamese runtime captures. This gallery works offline; opening the source link is optional.</p></main>
<dialog id="viewer"><div class="viewerbar"><button id="prev">Previous</button><button id="next">Next</button><strong id="caption"></strong><button id="mode">Show full page</button><button id="close">Close</button></div><div class="picture"><img id="large" alt="Studio page screenshot"></div></dialog>
<script>const DATA=__DATA__;let size='desktop',visible=[],current=0,full=false;const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function draw(){const section=$('#section').value,q=$('#search').value.toLowerCase();visible=DATA.results.filter(r=>r.size===size&&(section==='All sections'||r.group===section)&&(r.title+' '+r.key+' '+r.group).toLowerCase().includes(q));$('#count').textContent=visible.length+' screen states · '+size;$('#pages').innerHTML=['Home','Family','Game','Analytics','Setup'].map(g=>{const rows=visible.filter(r=>r.group===g);return rows.length?'<section class="group"><h2>'+g+'</h2><div class="grid">'+rows.map(r=>'<article class="card"><p class="small">'+esc(r.group)+' · '+esc(r.key)+'</p><h3>'+esc(r.title)+'</h3><button data-open="'+visible.indexOf(r)+'" style="display:block;width:100%;padding:0;border:0"><img loading="lazy" src="'+esc(r.viewport||r.image)+'" alt="'+esc(r.title)+'"></button>'+(r.messages?.length?'<p class="flag">Unavailable/error state captured; open image for details.</p>':'')+(r.notes||[]).filter(n=>!n.includes('Synthetic sign-in')).map(n=>'<p class="small">'+esc(n)+'</p>').join('')+'<div class="links"><a href="'+esc(r.viewport||r.image)+'" target="_blank">First screen</a><a href="'+esc(r.image)+'" target="_blank">Full page / overview</a></div></article>').join('')+'</div></section>':''}).join('');document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{current=+b.dataset.open;full=false;show();$('#viewer').showModal()})}
function show(){const r=visible[current];$('#caption').textContent=(current+1)+' / '+visible.length+' · '+r.group+' · '+r.title+' · '+size;$('#large').src=full?r.image:(r.viewport||r.image);$('#large').alt=r.title+' '+(full?'full page':'first screen');$('#mode').textContent=full?'Show first screen':'Show full page';$('#prev').disabled=current===0;$('#next').disabled=current===visible.length-1;$('.picture').scrollTop=0}
document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{size=b.dataset.size;document.querySelectorAll('[data-size]').forEach(n=>n.setAttribute('aria-pressed',n===b));draw()});$('#section').onchange=draw;$('#search').oninput=draw;$('#prev').onclick=()=>{current--;show()};$('#next').onclick=()=>{current++;show()};$('#mode').onclick=()=>{full=!full;show()};$('#close').onclick=()=>$('#viewer').close();draw();</script></html>'''
(root/'index.html').write_text(page.replace('__DATA__',payload))
pdf=canvas.Canvas(str(root/'Studio-all-pages-desktop.pdf'),pagesize=landscape(A4));pdf.setTitle('Sparkle Studio — all 41 pages, owner review');pdf.setAuthor('Sparkle Valley Studio review');w,h=landscape(A4)
desktop=[r for r in rows if r['size']=='desktop'];last=None
for i,r in enumerate(desktop,1):
 key='page-'+r['key'];pdf.bookmarkPage(key)
 if r['group']!=last:pdf.addOutlineEntry(r['group'],key,level=0);last=r['group']
 pdf.addOutlineEntry(r['title'],key,level=1)
 pdf.setFillColorRGB(.17,.12,.27);pdf.setFont('Helvetica-Bold',15);pdf.drawString(24,h-25,r['group']+' / '+r['title'])
 pdf.setFont('Helvetica',9);pdf.drawString(24,h-41,'Synthetic preview — current online Studio UI; not production data or a verified live SQL connection.')
 img=ImageReader(str(root/(r.get('viewport') or r['image'])));iw,ih=img.getSize();scale=min((w-48)/iw,(h-83)/ih);dw,dh=iw*scale,ih*scale
 pdf.drawImage(img,(w-dw)/2,28+(h-83-dh)/2,width=dw,height=dh)
 pdf.setFont('Helvetica',8);pdf.drawString(24,12,'Full-page/overview PNGs and phone/tablet views are in the screenshot archive. Source app35bffe6a.')
 pdf.drawRightString(w-24,12,str(i)+' / '+str(len(desktop)));pdf.showPage()
pdf.save()
(root/'README.md').write_text('''# Every Studio page — screenshot review\n\n27 October 2026 AEDT. Open **index.html** for the offline gallery, or **Studio-all-pages-desktop.pdf** for a bookmarked desktop review.\n\nThe gallery covers all **41 Studio pages**, the **Family, Game and Setup section menus**, and **sign-in**, each at **1440×1000 desktop**, **820×1180 tablet**, and **390×844 phone**: 135 screen states. First-screen and full-page images are provided; very long pages use an explicitly labelled collapsed overview.\n\nThese are real browser captures of the implemented online Studio and routes with synthetic in-memory records/providers. No production sign-in, paid provider, deployment, real invoice or family data is used. Empty/unavailable states are kept visible. Finance fixtures use ExampleOnly/DEMO-ONLY identifiers. The Windows executable and live Netlify SQL connection are not verified by this review.\n\nThe default gallery starts with Home, Family and Game, then Analytics and Setup. Use section/search filters, device buttons and Previous/Next. Source app commit: `35bffe6ad5d8ca757ed60a49be670bca08b38f86`.\n\nCapture metadata and any observed browser/layout issues are in **captures.json**. Reproduce with `PLAYWRIGHT_BROWSERS_PATH=/workspace/.cache/ms-playwright node docs/studio-page-review-20261027/tools/capture.mjs`, then `python docs/studio-page-review-20261027/tools/build.py`. The capture helper only uses local synthetic services. It is never a production action.\n''')
print('Built gallery:',len(rows),'screen states; desktop PDF:',len(desktop),'pages')
